public class CodeGeneratorTest{
private CodeGenerator cg;
    private MockCodeConsumer mcc;

    @Before
    public void setUp() throws Exception {
        mcc = new MockCodeConsumer();
        cg = new CodeGenerator(mcc);
    }

    @Test
    public void testContinueProcessing() throws Exception {
        cg.add(new Node(Token.NUMBER), CodeGenerator.Context.OTHER);
        assertThat(mcc.toString(), is("42"));
    }

    @Test
    public void testBinaryOperator() throws Exception {
        Node n = new Node(Token.ADD);
        n.addChildToBack(new Node(Token.NUMBER).setDouble(1));
        n.addChildToBack(new Node(Token.NUMBER).setDouble(2));
        cg.add(n, CodeGenerator.Context.OTHER);
        assertThat(mcc.toString(), is("1 + 2"));
    }

    @Test
    public void testUnaryOperator() throws Exception {
        Node n = new Node(Token.NOT);
        n.addChildToBack(new Node(Token.NUMBER).setDouble(1));
        cg.add(n, CodeGenerator.Context.OTHER);
        assertThat(mcc.toString(), is("!1"));
    }

    @Test
    public void testTryCatch() throws Exception {
        Node n = new Node(Token.TRY);
        Node block = new Node(Token.BLOCK);
        block.addChildToBack(new Node(Token.NUMBER).setDouble(1));
        n.addChildToBack(block);
        Node catchBlock = new Node(Token.CATCH);
        catchBlock.addChildToBack(new Node(Token.NAME).setString("e"));
        Node catchBlockBody = new Node(Token.BLOCK);
        catchBlockBody.addChildToBack(new Node(Token.NUMBER).setDouble(2));
        catchBlock.addChildToBack(catchBlockBody);
        n.addChildToBack(catchBlock);
        cg.add(n, CodeGenerator.Context.OTHER);
        assertThat(mcc.toString(), is("try{1}catch(e){2}"));
    }

    @Test
    public void testThrow() throws Exception {
        Node n = new Node(Token.THROW);
        n.addChildToBack(new Node(Token.NUMBER).setDouble(1));
        cg.add(n, CodeGenerator.Context.OTHER);
        assertThat(mcc.toString(), is("throw 1;"));
    }

    @Test
    public void testReturn() throws Exception {
        Node n = new Node(Token.RETURN);
        n.addChildToBack(new Node(Token.NUMBER).setDouble(1));
        cg.add(n, CodeGenerator.Context.OTHER);
        assertThat(mcc.toString(), is("return 1;"));
    }

    @Test
    public void testVar() throws Exception {
