    @Test
    public void testLargeFile() throws Exception {
        // Create a large file
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream taos = new TarArchiveOutputStream(baos);
        TarArchiveEntry entry = new TarArchiveEntry("largefile");
        entry.setSize(10 * 1024 * 1024); // 10MB
        taos.putArchiveEntry(entry);
        byte[] buffer = new byte[1024];
        for (int i = 0; i < 10 * 1024; i++) {
            taos.write(buffer);
        }
        taos.closeArchiveEntry();
        taos.close();

        // Read the large file
        ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
        TarArchiveInputStream tais = new TarArchiveInputStream(bais);
        TarArchiveEntry readEntry = tais.getNextTarEntry();
        assertThat(readEntry.getName(), equalTo("largefile"));
        assertThat(readEntry.getSize(), equalTo(10 * 1024 * 1024L));
        byte[] readBuffer = new byte[1024];
        long totalRead = 0;
        while (totalRead < readEntry.getSize()) {
            int read = tais.read(readBuffer);
            totalRead += read;
        }
        assertThat(totalRead, equalTo(readEntry.getSize()));
        tais.close();
    }
}
