        crc.update((byte) 'e');
        crc.update((byte) 'l');
        crc.update((byte) 'l');
        crc.update((byte) 'o');
        final long crcValue = crc.getValue();
        putLong(data, LFH_SIG.length, crcValue);
        // CSize
