public class ChangeSetPerformerTest{
private ChangeSetPerformer performer;
    private ChangeSet changeSet;
    private ArchiveInputStream in;
    private ArchiveOutputStream out;

    @Before
    public void setUp() throws Exception {
        changeSet = mock(ChangeSet.class);
        when(changeSet.getChanges()).thenReturn(new LinkedHashSet<>());
        performer = new ChangeSetPerformer(changeSet);
        in = mock(ArchiveInputStream.class);
        out = mock(ArchiveOutputStream.class);
    }

    @After
    public void tearDown() throws Exception {
    }

    @Test
    public void testPerformEmptyChangeSet() throws Exception {
        ChangeSetResults results = performer.perform(in, out);
        verify(out).finish();
        assertTrue(results.getAdded().isEmpty());
        assertTrue(results.getDeleted().isEmpty());
    }

    @Test
    public void testPerformAddFile() throws Exception {
        Change change = mock(Change.class);
        when(change.type()).thenReturn(Change.TYPE_ADD);
        when(change.isReplaceMode()).thenReturn(true);
        ArchiveEntry entry = mock(ArchiveEntry.class);
        when(change.getEntry()).thenReturn(entry);
        when(change.getInput()).thenReturn(mock(InputStream.class));
        ((LinkedHashSet<Change>)changeSet.getChanges()).add(change);

        ChangeSetResults results = performer.perform(in, out);
        verify(out).finish();
        assertEquals(1, results.getAdded().size());
        assertTrue(results.getDeleted().isEmpty());
    }

    @Test
    public void testPerformDeleteFile() throws Exception {
        Change change = mock(Change.class);
        when(change.type()).thenReturn(Change.TYPE_DELETE);
        when(change.targetFile()).thenReturn("test.txt");
        ((LinkedHashSet<Change>)changeSet.getChanges()).add(change);

        ArchiveEntry entry = mock(ArchiveEntry.class);
        when(entry.getName()).thenReturn("test.txt");
        when(in.getNextEntry()).thenReturn(entry, (ArchiveEntry)null);

        ChangeSetResults results = performer.perform(in, out);
        verify(out).finish();
        assertTrue(results.getAdded().isEmpty());
        assertEquals(1, results.getDeleted().size());
    }

    @Test
    public void testPerformDeleteDir() throws Exception {
        Change change = mock(Change.class);
        when(change.type()).thenReturn(Change.TYPE_DELETE_DIR);
        when(change.targetFile()).thenReturn("dir");
        ((LinkedHashSet<Change>)changeSet.getChanges()).add(change);

        ArchiveEntry entry = mock(ArchiveEntry.class);
        when(entry.getName()).thenReturn("dir/test.txt");
        when(in.getNextEntry()).thenReturn(entry, (ArchiveEntry)null);

        ChangeSetResults results = performer.perform(in, out);
        verify(out).finish();
        assertTrue(results.getAdded().isEmpty());
        assertEquals(1, results.getDeleted().size());
    }

    @Test
