        assertEquals(1, results.getAdded().size());
        assertTrue(results.getDeleted().isEmpty());
    }

    @Test
    public void testPerformIOException() throws Exception {
        IOException exception = new IOException();
        doThrow(exception).when(out).finish();

        Change change = mock(Change.class);
        when(change.type()).thenReturn(Change.TYPE_ADD);
        when(change.isReplaceMode()).thenReturn(true);
        ArchiveEntry entry = mock(ArchiveEntry.class);
        when(change.getEntry()).thenReturn(entry);
        when(change.getInput()).thenReturn(mock(InputStream.class));
        ((LinkedHashSet<Change>)changeSet.getChanges()).add(change);

        try {
            performer.perform(in, out);
            fail("Expected IOException");
        } catch (IOException e) {
            assertSame(exception, e);
        }
    }

    @Test
    public void testPerformMultipleChanges() throws Exception {
        Change addChange = mock(Change.class);
        when(addChange.type()).thenReturn(Change.TYPE_ADD);
        when(addChange.isReplaceMode()).thenReturn(true);
        ArchiveEntry addEntry = mock(ArchiveEntry.class);
        when(addChange.getEntry()).thenReturn(addEntry);
        when(addChange.getInput()).thenReturn(mock(InputStream.class));

        Change deleteChange = mock(Change.class);
        when(deleteChange.type()).thenReturn(Change.TYPE_DELETE);
        when(deleteChange.targetFile()).thenReturn("test.txt");

        ((LinkedHashSet<Change>)changeSet.getChanges()).add(addChange);
        ((LinkedHashSet<Change>)changeSet.getChanges()).add(deleteChange);

        ArchiveEntry entry = mock(ArchiveEntry.class);
        when(entry.getName()).thenReturn("test.txt");
        when(in.getNextEntry()).thenReturn(entry, (ArchiveEntry)null);

        ChangeSetResults results = performer.perform(in, out);
        verify(out).finish();
        assertEquals(1, results.getAdded().size());
        assertEquals(1, results.getDeleted().size());
    }
}
