private JsonParserSequence jsonParserSequence;
    private JsonParser[] parsers;
    @Before
    public void init(){
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);
        when(parser1.nextToken()).thenReturn(JsonToken.START_OBJECT);
        when(parser2.nextToken()).thenReturn(JsonToken.END_OBJECT);
        when(parser1.hasCurrentToken()).thenReturn(true);
        when(parser2.hasCurrentToken()).thenReturn(false);
        when(parser1.currentToken()).thenReturn(JsonToken.START_OBJECT);
        when(parser2.currentToken()).thenReturn(JsonToken.END_OBJECT);
        parsers = new JsonParser[]{parser1, parser2};
    }

    @Test
    public void testNextTokenDelegateNull() throws IOException {
        jsonParserSequence = new JsonParserSequence(new JsonParser[]{null});
        Assert.assertNull(jsonParserSequence.nextToken());
    }

    @Test
    public void testNextTokenSuppressNextToken() throws IOException {
        jsonParserSequence = new JsonParserSequence(parsers);
        jsonParserSequence._suppressNextToken = true;
        JsonToken token = jsonParserSequence.nextToken();
        Assert.assertEquals(JsonToken.START_OBJECT, token);
    }

    @Test
    public void testNextTokenSingleParser() throws IOException {
        jsonParserSequence = new JsonParserSequence(new JsonParser[]{parsers[0]});
        JsonToken token = jsonParserSequence.nextToken();
        Assert.assertEquals(JsonToken.START_OBJECT, token);
    }

    @Test
    public void testNextTokenMultipleParsers() throws IOException {
        jsonParserSequence = new JsonParserSequence(parsers);
        JsonToken token = jsonParserSequence.nextToken();
        Assert.assertEquals(JsonToken.START_OBJECT, token);
        token = jsonParserSequence.nextToken();
        Assert.assertEquals(JsonToken.END_OBJECT, token);
        Assert.assertNull(jsonParserSequence.nextToken());
    }

    @Test
    public void testSwitchToNext() throws IOException {
        jsonParserSequence = new JsonParserSequence(parsers);
        jsonParserSequence._nextParser = 0;
        Assert.assertTrue(jsonParserSequence.switchToNext());
        Assert.assertEquals(1, jsonParserSequence._nextParser);
    }

    @Test
    public void testSwitchToNextLastParser() throws IOException {
        jsonParserSequence = new JsonParserSequence(parsers);
        jsonParserSequence._nextParser = 1;
        Assert.assertFalse(jsonParserSequence.switchToNext());
    }

    @Test
    public void testClose() throws IOException {
        jsonParserSequence = new JsonParserSequence(parsers);
        jsonParserSequence.close();
        // close should not throw any exception
    }

    @Test
    public void testContainedParsersCount() {
        jsonParserSequence = new JsonParserSequence(parsers);
        Assert.assertEquals(2, jsonParserSequence.containedParsersCount());
    }

