        jsonGenerator.writeEmbeddedObject(object);
        verify(jsonGenerator,times(1)).writeNull();

        // Test case 2: object is byte array
        byte[] bytes = {1,2,3};
        jsonGenerator.writeEmbeddedObject(bytes);
        verify(jsonGenerator,times(1)).writeBinary(bytes);

        // Test case 3: object is not supported
        Object unsupportedObject = new Object();
        try{
            jsonGenerator.writeEmbeddedObject(unsupportedObject);
            Assert.fail();
        }catch (JsonGenerationException e){
            assertThat(e.getMessage(),is("No native support for writing embedded objects of type "+unsupportedObject.getClass().getName()));
