public class AsKeyTest{
@Test
    public void testToString_RawNull() throws Exception {
        AsKey testClass =  getAsKeyInstance(null, null, 1);
        Assert.assertEquals("null<>", testClass.toString());
    }

    @Test
    public void testToString_RawNotNull() throws Exception {
        Class<?> raw = String.class;
        AsKey testClass =  getAsKeyInstance(raw, null, 1);
        Assert.assertEquals("java.lang.String<>", testClass.toString());
    }

    @Test
    public void testToString_ParamsNotNull() throws Exception {
        Class<?> raw = String.class;
        JavaType[] params = new JavaType[1];
        AsKey testClass =  getAsKeyInstance(raw, params, 1);
        Assert.assertEquals("java.lang.String<>", testClass.toString());
    }

    @Test
    public void testEquals() throws Exception {
        AsKey testClass1 =  getAsKeyInstance(String.class, null, 1);
        AsKey testClass2 =  getAsKeyInstance(String.class, null, 1);
        Assert.assertTrue(testClass1.equals(testClass2));
    }

    @Test
    public void testEquals_False() throws Exception {
        AsKey testClass1 =  getAsKeyInstance(String.class, null, 1);
        AsKey testClass2 =  getAsKeyInstance(Integer.class, null, 1);
        Assert.assertFalse(testClass1.equals(testClass2));
    }

    @Test
    public void testEquals_Null() throws Exception {
        AsKey testClass =  getAsKeyInstance(String.class, null, 1);
        Assert.assertFalse(testClass.equals(null));
    }

    @Test
    public void testEquals_NotAsKey() throws Exception {
        AsKey testClass =  getAsKeyInstance(String.class, null, 1);
        Assert.assertFalse(testClass.equals(""));
    }

    @Test
    public void testHashCode() throws Exception {
        AsKey testClass1 =  getAsKeyInstance(String.class, null, 1);
        AsKey testClass2 =  getAsKeyInstance(String.class, null, 1);
        Assert.assertEquals(testClass1.hashCode(), testClass2.hashCode());
    }

    @Test
    public void testHashCode_False() throws Exception {
        AsKey testClass1 =  getAsKeyInstance(String.class, null, 1);
        AsKey testClass2 =  getAsKeyInstance(Integer.class, null, 2);
        Assert.assertNotEquals(testClass1.hashCode(), testClass2.hashCode());
    }

    private AsKey getAsKeyInstance(Class<?> raw, JavaType[] params, int hash) throws Exception {
        Constructor<AsKey> constructor = AsKey.class.getDeclaredConstructor(Class.class, JavaType[].class, int.class);
        constructor.setAccessible(true);
        return constructor.newInstance(raw, params, hash);
    }
}
