            throw new RuntimeException(e);
        }
    }

    private Element createElement(String name, String namespaceURI) {
        Document document = createDocument();
        Element element = document.createElementNS(namespaceURI, name);
        document.getDocumentElement().appendChild(element);
        return element;
    }

    private Node createTextNode(String text) {
        Document document = createDocument();
        Node node = document.createTextNode(text);
        document.getDocumentElement().appendChild(node);
        return node;
    }

    private Node createCommentNode(String comment) {
        Document document = createDocument();
        Comment commentNode = document.createComment(comment);
        document.getDocumentElement().appendChild(commentNode);
        return commentNode;
    }

    private Node createProcessingInstructionNode(String target, String data) {
        Document document = createDocument();
        ProcessingInstruction processingInstruction = document.createProcessingInstruction(target, data);
        document.getDocumentElement().appendChild(processingInstruction);
        return processingInstruction;
