    public void testInvalidLowerBound(){
        bobyqaOptimizer.optimize(new MultivariateFunction(){
            @Override
            public double value(double[] point) {
                return 0;
            }
        }, GoalType.MAXIMIZE, new double[]{-1,0}, new double[]{1,1});
    }

    @Test(expected=NumberIsTooSmallException.class)
    public void testInvalidUpperBound(){
        bobyqaOptimizer.optimize(new MultivariateFunction(){
            @Override
            public double value(double[] point) {
                return 0;
            }
        }, GoalType.MAXIMIZE, new double[]{0,0}, new double[]{-1,1});
    }

    @Test(expected=NumberIsTooSmallException.class)
    public void testInvalidLowerUpperBound(){
        bobyqaOptimizer.optimize(new MultivariateFunction(){
            @Override
            public double value(double[] point) {
                return 0;
            }
        }, GoalType.MAXIMIZE, new double[]{0,0}, new double[]{1,1});
    }

    @Test
    public void testOptimize(){
        MultivariateFunction f = new MultivariateFunction(){
            @Override
            public double value(double[] point) {
                return -Math.pow(point[0],2) - Math.pow(point[1],2);
            }
        };
        RealPointValuePair result = bobyqaOptimizer.optimize(f, GoalType.MINIMIZE, new double[]{Double.NEGATIVE_INFINITY, Double.NEGATIVE_INFINITY}, new double[]{Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY});
        assertNotNull(result);
        assertEquals(2, result.getPoint().length);
        assertTrue(Arrays.equals(new double[]{0, 0}, result.getPoint(), 1e-6));
    }

    @Test
    public void testMaximize(){
        MultivariateFunction f = new MultivariateFunction(){
            @Override
            public double value(double[] point) {
                return Math.pow(point[0],2) + Math.pow(point[1],2);
            }
        };
        RealPointValuePair result = bobyqaOptimizer.optimize(f, GoalType.MAXIMIZE, new double[]{Double.NEGATIVE_INFINITY, Double.NEGATIVE_INFINITY}, new double[]{Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY});
        assertNotNull(result);
        assertEquals(2, result.getPoint().length);
        assertTrue(Arrays.equals(new double[]{Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY}, result.getPoint(), 1e-6) ||
                   Arrays.equals(new double[]{Double.NEGATIVE_INFINITY, Double.NEGATIVE_INFINITY}, result.getPoint(), 1e-6));
    }

