    public void tearDown() throws Exception {
    }

    @Test
    public void areEqual_sameInstance() {
        Object o = new Object();
        assertTrue(Equality.areEqual(o, o));
    }

    @Test
    public void areEqual_bothNull() {
        assertTrue(Equality.areEqual(null, null));
    }

    @Test
    public void areEqual_oneNull() {
        assertFalse(Equality.areEqual(null, new Object()));
        assertFalse(Equality.areEqual(new Object(), null));
    }

    @Test
    public void areEqual_arrays() {
        Object[] a1 = {1, 2, 3};
        Object[] a2 = {1, 2, 3};
        Object[] a3 = {1, 2, 4};
        assertTrue(Equality.areEqual(a1, a1));
        assertTrue(Equality.areEqual(a1, a2));
        assertFalse(Equality.areEqual(a1, a3));
    }

    @Test
    public void areEqual_notArrays() {
        assertTrue(Equality.areEqual("hello", "hello"));
        assertFalse(Equality.areEqual("hello", "world"));
    }

    @Test
    public void areEqual_mixedTypes() {
        assertFalse(Equality.areEqual("hello", 123));
    }
}
